import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Project each row onto _FIELDS as strings.

    Missing or None values become ''; other values are stringified. Order is
    preserved, and the input rows are only read, never modified. Consuming
    `rows` happens exactly once, so one-shot iterables are supported.
    """
    clean = []
    for row in rows:
        clean_row = {}
        for key in _FIELDS:
            value = row.get(key)
            clean_row[key] = "" if value is None else str(value)
        clean.append(clean_row)
    return clean


def _serialize_csv(clean):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for row in clean:
        writer.writerow([row[key] for key in _FIELDS])
    return buffer.getvalue()


def _serialize_json(clean):
    return json.dumps(clean, ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {
    "csv": _serialize_csv,
    "json": _serialize_json,
}


def export_rows(rows, format):
    """Export rows as 'csv' or 'json'. Raises ValueError for other formats.

    The format is checked before `rows` is read, so an unsupported format
    leaves the input untouched.
    """
    try:
        serialize = _SERIALIZERS[format]
    except (KeyError, TypeError):
        raise ValueError("unsupported format") from None
    return serialize(_normalize(rows))
